import React, { useState } from 'react';
import { mediaAPI } from '../services/api';

function MediaUpload({ onUpload }) {
  const [formData, setFormData] = useState({
    title: '',
    caption: '',
    location: '',
    people: '',
    mediaType: 'image'
  });
  const [file, setFile] = useState(null);

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleFileChange = (e) => {
    setFile(e.target.files[0]);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!file) {
      alert('Please select a file');
      return;
    }

    const uploadData = new FormData();
    uploadData.append('file', file);
    uploadData.append('title', formData.title);
    uploadData.append('caption', formData.caption);
    uploadData.append('location', formData.location);
    uploadData.append('people', formData.people);
    uploadData.append('mediaType', formData.mediaType);

    try {
      await mediaAPI.upload(uploadData);
      setFormData({
        title: '',
        caption: '',
        location: '',
        people: '',
        mediaType: 'image'
      });
      setFile(null);
      onUpload();
    } catch (error) {
      console.error('Error uploading media:', error);
      alert('Error uploading media');
    }
  };

  return (
    <div className="media-upload">
      <h3>Upload Media</h3>
      <form onSubmit={handleSubmit}>
        <div>
          <label>Media Type:</label>
          <select name="mediaType" value={formData.mediaType} onChange={handleChange}>
            <option value="image">Image</option>
            <option value="video">Video</option>
          </select>
        </div>
        <div>
          <label>Title:</label>
          <input
            type="text"
            name="title"
            value={formData.title}
            onChange={handleChange}
            required
          />
        </div>
        <div>
          <label>Caption:</label>
          <input
            type="text"
            name="caption"
            value={formData.caption}
            onChange={handleChange}
            required
          />
        </div>
        <div>
          <label>Location:</label>
          <input
            type="text"
            name="location"
            value={formData.location}
            onChange={handleChange}
            required
          />
        </div>
        <div>
          <label>People (comma-separated):</label>
          <input
            type="text"
            name="people"
            value={formData.people}
            onChange={handleChange}
          />
        </div>
        <div>
          <label>File:</label>
          <input
            type="file"
            accept="image/*,video/*"
            onChange={handleFileChange}
            required
          />
        </div>
        <button type="submit">Upload</button>
      </form>
    </div>
  );
}

export default MediaUpload;
